//! 🧪️ Actual prepared edit/root/seal custody includes every original allocator extent.
use super::*;
use semio_framework_value::retirement::{OwnedValueRetirementFactory,SharedValueRetirementFactory};
#[test]
fn prepared_candidate_original_owners_retire_with_actual_allocator_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for body in law["copyGrants"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;
 let((prepared,mutations,snapshots),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let authority=Arc::new(ArtifactStoreOneItemLiveAuthority{operation:semio_framework_job::OperationId(11),generation:semio_framework_job::Generation(7),base_revision:[9;32],base_applied_edit_count:3,next_sequence_number:4,next_clock:HybridLogicalTimestamp{actor:1,physical_ms:42,logical:2},actor:law["identities"][0].as_str().unwrap().into(),line:None,group_id:None,stamped_edit_id:Some(law["identities"][1].as_str().unwrap().into())});let mut payload=String::with_capacity(4096);payload.push_str(law["payload"].as_str().unwrap());let edit=authority.next_edit(payload.clone(),vec![payload.clone()]);let prepared=authority.prepare_one_item(edit,Arc::new(payload)).unwrap();let mutations:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(OwnedValueRetirementFactory::<String>::default());let snapshots:Arc<dyn SnapshotRetirementFactory<String>>=Arc::new(SharedValueRetirementFactory::<String>::default());(prepared,mutations,snapshots)});let held=heap.requested_bytes-heap.released_bytes;let edit_pointer=prepared.edit.as_ref()as*const Edit<String>;let post_pointer=Arc::as_ptr(&prepared.post_snapshot);let mutation_pointer=Arc::as_ptr(&mutations);let snapshot_pointer=Arc::as_ptr(&snapshots);let birth=ArtifactStoreOneItemPrepared::<String,String>::retirement_birth_demand();let grant=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:birth.capacity_bytes-1,maximum_depth:birth.depth,..Default::default()};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||prepared.admit_retirement(mutations,snapshots,grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(_,prepared,mutations,snapshots)=match result{Err(original)=>original,Ok(_)=>panic!("unfunded original prepared admission succeeded")};assert_eq!(prepared.edit.as_ref()as*const Edit<String>,edit_pointer);assert_eq!(Arc::as_ptr(&prepared.post_snapshot),post_pointer);assert!(std::ptr::addr_eq(Arc::as_ptr(&mutations),mutation_pointer));assert!(std::ptr::addr_eq(Arc::as_ptr(&snapshots),snapshot_pointer));let grant=RetainedCloneGrant{maximum_capacity_bytes:birth.capacity_bytes,..grant};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||prepared.admit_retirement(mutations,snapshots,grant));let(owner,receipt)=result.unwrap_or_else(|_|panic!("actual prepared frame refused exact admission"));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,0));let(mut born,mut released)=(heap.requested_bytes,0);let mut owner=Some(owner);
 for turn in 0..1000000{let Some(active)=owner.as_ref()else{break};let demand=artifact_retirement_box_demands(active,body).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes.max(body),maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for under in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:0,..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant})].into_iter().flatten(){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||artifact_retirement_box_close_step(&mut owner,under));if let Ok(step)=result{assert_eq!(step.progress(),Default::default());}assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||artifact_retirement_box_close_step(&mut owner,grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;assert!(turn<999999);}
 assert!(owner.is_none());assert_eq!(released,held+born);eprintln!("[DEBUG] Actual prepared originalBox={edit_pointer:p} originalPost={post_pointer:p} copy={body} original={held} born={born} released={released} terminal=true");
 }
}